def balanced_brackets(s):
    stack = []

    for char in s:
        if char == '(' or char == '[' or char == '{':
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack:
                return False
            last_char = stack.pop()
            if (last_char == '(' and char != ')') or \
               (last_char == '[' and char != ']') or \
               (last_char == '{' and char != '}'):
                return False
    return len(stack) == 0

