def merge_intervals(intervals):
    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = []
    for interval in intervals:
        # If the current interval does not overlap with the last merged interval
        if not merged or merged[-1][1] < interval[0]:
            # Add the current interval to the merged list
            merged.append(interval)
        else:
            # Otherwise, merge it with the last interval in the merged list
            merged[-1][1] = max(merged[-1][1], interval[1])

    return merged

def merge_intervals(intervals):
    # Sort intervals by start in ascending order, then by end in descending order
    intervals.sort(key=lambda x: (x[0], -x[1]))

    merged = []
    for start, end in intervals:
        # If the current interval does not overlap with the last merged interval
        if not merged or merged[-1][1] < start:
            # Add the current interval to the merged list
            merged.append((start, end))
        else:
            # Merge with the last interval if it overlaps
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))

    return merged

