        cleaned_word = ''.join(char.lower() for char in word if char.isalnum())

        # If the cleaned word is not already a key in the dictionary, add it with a count of 1
        if cleaned_word not in frequency_dict:
            frequency_dict[cleaned_word] = 1
        # If the cleaned word is already a key in the dictionary, increment its count by 1
        else:
            frequency_dict[cleaned_word] += 1

