def is_rotation(a, b):
    # Check if the lengths of a and b are equal
    if len(a) != len(b):
        return False

    # Check if b is a substring of a
    if b in a:
        return True

    # Check for rotations
    for i in range(len(a)):
        if a[i:] == b and a[:i] == b:
            return True

    # If none of the above conditions are met, they are not rotations
    return False

