def chunk(lst, n):
    if n <= 0:
        raise ValueError("n must be greater than zero")

    # If the list is empty, return an empty list
    if not lst:
        return []

    # If the length of the list is divisible by n, split it into chunks
    if len(lst) % n == 0:
        return [lst[i:i+n] for i in range(0, len(lst), n)]
    else:
        # If the length is not divisible by n, calculate the number of chunks
        num_chunks = len(lst) // n

        # Create the list of chunks
        return [lst[i:i+n] for i in range(0, len(lst), n)][:num_chunks]

