def int_to_roman(n):
    """
    Convert an integer in the range 1..3999 to its standard Roman numeral string.
    Subtractive forms (4 -> IV, 9 -> IX, 40 -> XL, 90 -> XC, 400 -> CD, 900 -> CM)
    """
    roman_numerals = {
        1: 'I', 4: 'IV', 5: 'V', 9: 'IX',
        10: 'X', 40: 'XL', 50: 'L', 90: 'XC',
        100: 'C', 400: 'CD', 500: 'D', 900: 'CM',
        1000: 'M'
    }
    result = []

    for value, numeral in sorted(roman_numerals.items(), reverse=True):
        while n >= value:
            result.append(numeral)
            n -= value

    return ''.join(result)

# Test cases
assert int_to_roman(9) == "IX"
assert int_to_roman(13) == "XIII"

