def group_anagrams(words):
    # Create a dictionary to store the grouped words and their sorted order
    anagrams = {}

    # Iterate through each word in the input list
    for word in words:
        # Sort the characters of the word and create a key for that sorted word
        key = ''.join(sorted(word))

        # If the key is not in the dictionary, add it with a value of an empty list
        if key not in anagrams:
            anagrams[key] = []

        # Append the word to the corresponding list in the dictionary
        anagrams[key].append(word)

    # Convert the dictionary keys back to a list and return it
    return list(anagrams.keys())

