def count_islands(grid):
    """
    Counts connected groups of 1s in a grid, ORTHOGONALLY only (up/down/left/right),
    not diagonally. Empty grids return 0.

    :param grid: A 2D list of integers (0s and 1s)
    :return: The number of connected groups of 1s
    """
    if not grid or '0' in grid:
        return 0

    rows, cols = len(grid), len(grid[0])

    def dfs(x, y):
        if grid[x][y] == '1':
            grid[x][y] = '#'

            if x > 0 and grid[x-1][y] == '1':
                dfs(x-1, y)
            if x < rows - 1 and grid[x+1][y] == '1':
                dfs(x+1, y)
            if y > 0 and grid[x][y-1] == '1':
                dfs(x, y-1)
            if y < cols - 1 and grid[x][y+1] == '1':
                dfs(x, y+1)

    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '1':
                dfs(i, j)
                count += 1

    return count

