def validate_ipv4(s):
    # Split the string into parts based on '.'
    parts = s.split('.')

    # Check if there are exactly four parts
    if len(parts) != 4:
        return False

    # Check each part for a valid IPv4 address
    for part in parts:
        if not part.isdigit() or int(part) < 0 or int(part) > 255:
            return False

    # Check if the first part is not '0'
    if parts[0] == '0':
        return False

    # If all checks pass, the address is valid
    return True

