def interleave(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        result.append(a[i])
        result.append(b[j])
        i += 1
        j += 1
    if i < len(a):
        result.extend(a[i:])
    if j < len(b):
        result.extend(b[j:])
    return result

def digital_root(n):
    # If n is 0, return 0 as the single digit
    if n == 0:
        return 0

    # Sum the digits of n, converting to string for easy digit extraction
    sum_digits = str(n).replace(' ', '')

    # Sum the digits until a single digit is obtained
    while len(sum_digits) > 1:
        sum_digits = str(sum(int(digit)) for digit in sum_digits)

    # Return the single digit
    return int(sum_digits[0])

