def find_duplicates(nums):
    # Sort the list and then iterate through it to find duplicates.
    nums.sort()
    for i in range(len(nums)):
        if i == 0 or nums[i] != nums[i-1]:
            # If the current number is different from the previous one,
            # it's a duplicate.
            yield nums[i]
    return []

def find_duplicates(nums):
    # Dictionary to store the frequency of each number
    freq = {}

    # Iterate through the list and count occurrences
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Filter out numbers that occur more than once
    duplicates = [num for num, count in freq.items() if count > 1]

    # Return the sorted list of duplicates
    return sorted(duplicates)

