def eval_expression(s):
    # Split the input string into tokens based on spaces
    tokens = s.split()

    # Initialize an empty stack to hold the operands and operators
    stack = []

    for token in tokens:
        if token.isdigit():
            # If the token is a digit, convert it to an integer and push onto stack
            stack.append(int(token))
        elif token == '+':
            # If the token is an operator, pop two operands from stack and push their sum onto stack
            if len(stack) < 2:
                return "Error: Insufficient operands"
            else:
                stack.pop()
                stack.pop()
                stack.append(stack.pop() + int(token))
        elif token == '-':
            # If the token is an operator, pop two operands from stack and push their difference onto stack
            if len(stack) < 2:
                return "Error: Insufficient operands"
            else:
                stack.pop()
                stack.pop()
                stack.append(stack.pop() - int(token))
        elif token == '*':
            # If the token is an operator, pop two operands from stack and push their product onto stack
            if len(stack) < 2:
                return "Error: Insufficient operands"
            else:
                stack.pop()
                stack.pop()
                stack.append(stack.pop() * int(token))
        elif token == '/':
            # If the token is an operator, pop two operands from stack and push their quotient onto stack
            if len(stack) < 2:
                return "Error: Insufficient operands"
            else:
                stack.pop()
                stack.pop()
                stack.append(stack.pop() // int(token))
        else:
            # If the token is not a digit or an operator, it's a constant
            return int(token)

    # If the stack is empty at the end, it means all operands were correctly evaluated
    return stack[0]

