def eval_expression(s):
    stack = []

    # Split the string by spaces to handle multiple operators
    tokens = s.split()

    for token in tokens:
        if token.isdigit():
            # Convert the number to an integer and push it onto the stack
            stack.append(int(token))
        elif token in "+-*/":
            # Evaluate the current operator
            if len(stack) < 2:
                raise ValueError("Not enough operands for operator")

            # Pop the last two elements from the stack
            a = stack.pop()
            b = stack.pop()

            # Perform the operation and push the result back onto the stack
            if token == '+':
                stack.append(b + a)
            elif token == '-':
                stack.append(b - a)
            elif token == '*':
                stack.append(b * a)
            elif token == '/':
                if b == 0:
                    raise ValueError("Division by zero")
                stack.append(b // a)

    # The final result is the only element left in the stack
    return stack[0]

