class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.lru_cache = {}

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        # Update the least recently used entry to point to the new key
        self.lru_cache[key] = self.cache.pop(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the least recently used entry to point to the new value
            self.lru_cache[key] = value
        else:
            # If key is not in cache, add it and the least recently used entry
            if len(self.cache) == self.capacity:
                # Remove the least recently used key from lru_cache
                del self.lru_cache[self.cache.popitem(last=False)[0]]
            # Add the new key with its value
            self.cache[key] = value

