def topo_sort(deps):
    from collections import defaultdict

    # Create a graph and initialize it with dependencies
    graph = defaultdict(list)
    for task, prerequisites in deps.items():
        for prerequisite in prerequisites:
            graph[prerequisite].append(task)

    # Depth-first search to find the topological sort
    visited = set()
    stack = []
    for task in graph:
        if len(graph[task]) == 0 or task not in visited:
            dfs(task, graph, stack, visited)

    # Reverse the order to get the correct topological sort
    return list(reversed(stack))

def dfs(task, graph, stack, visited):
    if task in visited:
        return
    visited.add(task)

    for prerequisite in graph[task]:
        dfs(prerequisite, graph, stack, visited)

