def topo_sort(deps):
    visited = set()
    stack = []

    for task in deps:
        if task not in visited:
            queue = [task]
            while queue:
                current_task = queue.pop(0)
                if current_task not in visited:
                    visited.add(current_task)
                    stack.append(current_task)
                    for prerequisite in deps[current_task]:
                        if prerequisite not in visited:
                            queue.append(prerequisite)

    return stack[::-1] if len(stack) == len(deps) else None

