def wildcard_match(s, p):
    """
    Check if the string s matches the pattern p.

    The pattern p is defined as '*' which means any sequence of characters,
    including an empty one, or '?' which matches exactly one character.

    Args:
    s (str): The string to be matched against the pattern.
    p (str): The pattern, which can include '*' and '?' as described above.

    Returns:
    bool: True if the string matches the pattern, False otherwise.
    """
    # If s is empty and p is empty, they match
    if not s and not p:
        return True

    # If the pattern is empty, check if s matches it
    if not p:
        return s == ""

    # If the pattern is a single character, check if it matches the current position of s
    if len(p) == 1:
        return s and wildcard_match(s[1:], p[0])

    # If the pattern has more than one character, check if it matches s with a wildcard
    if len(p) > 1:
        return wildcard_match(s, p[1:]) or wildcard_match(s[1:], p)

    # If the pattern is '*' and the string matches it, return True
    if p == '*':
        return wildcard_match(s, p[1:])

    # If the pattern is a single character and matches the current position of s, return True
    if p == '?':
        return wildcard_match(s[1:], p[0])

    # If none of the above conditions are met, return False
    return False

