def simplify_path(path):
    # Split the path into components based on slashes and remove duplicates.
    parts = [part for part in path.split('/') if part != '..']

    # Initialize the result with an empty string.
    result = ''

    for part in parts:
        # If the current component is a directory, add it to the result.
        if part == '..':
            if len(result) > 0:
                result = result[:-1]
        else:
            # If the current component is a file, add it to the result.
            if len(result) > 0:
                result += '/'
        # Append the component to the result.
        result += part

    return result

