def simplify_path(path):
    # Remove leading slashes and split the path into components
    components = path.replace('/', '').split('/')

    # Simplify each component by collapsing repeated slashes and removing '..'
    simplified_components = [
        '/' if i == 0 or path.startswith('/') else components[i - 1] + '/'
        for i, c in enumerate(components)
    ]

    # Join the simplified components back into a single path
    return '/' + '/'.join(simplified_components)

