def word_wrap(text, width):
    # Split the text into words and count the number of spaces
    word_count = len(text.split())

    # If width is less than or equal to 0, return an empty list
    if width <= 0:
        return []

    # If the number of spaces is greater than or equal to width, pack all words
    if word_count >= width:
        return [text]

    # Otherwise, pack the words into lines
    else:
        result = []
        for i in range(0, word_count, width):
            line = text[i:i+width]
            result.append(line)
        return result

