def longest_substring_k_distinct(s, k):
    """
    Finds the length of the longest contiguous substring with at most k distinct characters.

    :param s: The input string
    :param k: Maximum number of distinct characters allowed in the substring
    :return: Length of the longest contiguous substring with at most k distinct characters
    """
    if not s:
        return 0

    start, max_length = 0, 0
    char_frequency = {}

    for end in range(len(s)):
        if s[end] in char_frequency:
            char_frequency[s[end]] += 1
        else:
            char_frequency[s[end]] = 1

        while len(char_frequency) > k:
            char_frequency[s[start]] -= 1
            if char_frequency[s[start]] == 0:
                del char_frequency[s[start]]
            start += 1

        max_length = max(max_length, end - start + 1)

    return max_length

