def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []

    rows, cols = len(matrix), len(matrix[0])
    seen = [[False] * cols for _ in range(rows)]
    spiral, i, j, di, dj = [], 0, 0, 1, 0

    while len(spiral) < rows * cols:
        spiral.append(matrix[i][j])
        seen[i][j] = True
        new_i, new_j = i + di, j + dj

        if 0 <= new_i < rows and 0 <= new_j < cols and not seen[new_i][new_j]:
            i, j = new_i, new_j
        else:
            di, dj = -dj, di  # Change direction if we hit the edge or a seen cell

    return spiral

def spiral_order(matrix):
    if not matrix:
        return []

    rows, cols = len(matrix), len(matrix[0])
    order = []
    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for col in range(left, right + 1):
            order.append(matrix[top][col])

        # Traverse from top to bottom
        for row in range(top + 1, bottom + 1):
            order.append(matrix[row][right])

        # If there's a top row, traverse from right to left
        if top < bottom:
            for col in range(right - 1, left - 1, -1):
                order.append(matrix[bottom][col])

        # If there's a bottom row, traverse from bottom to top
        if left < right:
            for row in range(bottom - 1, top, -1):
                order.append(matrix[row][left])

        # Move to the next layer
        top += 1
        bottom -= 1
        left += 1
        right -= 1

    return order

