def validate_ipv4(s):
    # Split the string by '.' and check each part
    parts = s.split('.')

    if len(parts) != 4:
        return False

    for part in parts:
        # Check if the part is a valid IPv4 address
        if not re.match(r'^\d{1,3}$', part):
            return False

        # Check if the digit is not 0 and does not exceed 255
        if int(part) < 0 or int(part) > 255:
            return False

