def compare_versions(a, b):
    # Split version strings into components and pad with zeros as needed
    a_parts = [int(x) for x in str(a).split('.')]
    b_parts = [int(x) for x in str(b).split('.')]

    # Compare each component
    for i, (a_part, b_part) in enumerate(zip(a_parts, b_parts)):
        if a_part < b_part:
            return -1
        elif a_part > b_part:
            return 1

    # If all components are equal, the versions are considered equal
    return 0

