        return [int(part) for part in version_str.split('.') if part]

    a_parts = parse_version(a)
    b_parts = parse_version(b)

    for i in range(max(len(a_parts), len(b_parts))):
        a_val = a_parts[i] if i < len(a_parts) else 0
        b_val = b_parts[i] if i < len(b_parts) else 0

        if a_val > b_val:
            return 1
        elif a_val < b_val:
            return -1

