def parse_query_string(qs):
    result = {}
    pairs = qs.split('&')

    for pair in pairs:
        if '=' not in pair:
            result[pair] = []
        else:
            key, value = pair.split('=', 1)
            if key in result:
                if not isinstance(result[key], list):
                    result[key] = [result[key]]
                result[key].append(value)
            else:
                result[key] = value

    return result

