def topo_sort(deps):
    import collections

    in_degree = {task: 0 for task in deps}
    graph = collections.defaultdict(list)

    # Build the graph and in-degree map
    for task, predecessors in deps.items():
        for predecessor in predecessors:
            graph[predecessor].append(task)
            in_degree[task] += 1

    queue = [task for task in in_degree if in_degree[task] == 0]
    sorted_tasks = []

    while queue:
        task = queue.pop(0)
        sorted_tasks.append(task)

        for successor in graph[task]:
            in_degree[successor] -= 1
            if in_degree[successor] == 0:
                queue.append(successor)

    if len(sorted_tasks) < len(in_degree):
        return None
    else:
        return sorted_tasks

