        # Base case: if both strings are fully matched
        if i == 0 and j == 0:
            return True
        # If the pattern is empty, the string must also be empty to match
        if j == 0:
            return i == 0

        # If the pattern has a star '*', it can match zero or more characters
        if p[j-1] == '*':
            # Match zero occurrences of the preceding character or one occurrence
