    components = os.path.normpath(path).split(os.sep)

    # Process each component
    simplified_components = []
    for component in components:
        if component == '.' or not component:
            # Ignore empty strings and '.'
            continue
        elif component == '..':
            if simplified_components:
                # Remove the last component if it's '..'
                simplified_components.pop()
        else:
            # Add valid components
            simplified_components.append(component)

    # Reconstruct the path from components, joining with os.sep
    return os.path.join(os.sep, *simplified_components)

