        return str(int(digit_a) * int(digit_b))

    def add_strings(s1, s2):
        # Perform addition of two strings as if they were numbers
        carry = 0
        result = []
        i, j = len(s1) - 1, len(s2) - 1
        while i >= 0 or j >= 0:
            digit_sum = carry
            if i >= 0:
                digit_sum += int(s1[i])
                i -= 1
            if j >= 0:
                digit_sum += int(s2[j])
                j -= 1
            carry, digit = divmod(digit_sum, 10)
            result.append(str(digit))
        if carry:
            result.append(str(carry))
        return ''.join(result[::-1])

    if a == "0" or b == "0":
        return "0"

    # Reverse strings to make calculation easier
    a, b = a[::-1], b[::-1]
    result = ['0'] * (len(a) + len(b))

    for i in range(len(a)):
        for j in range(len(b)):
            product = multiply_digit(a[i], b[j])
            result[i + j] += product
            if i + j + 1 < len(result):
                result[i + j + 1] = str(int(result[i + j + 1]) + int(product[-1]))

    # Remove leading zeros
    while len(result) > 1 and result[0] == '0':
        del result[0]

    return ''.join(result[::-1])

