def word_wrap(text, width):
    if width <= 0:
        raise ValueError("Width must be greater than 0")

    words = text.split()
    if not words:
        return []

    line = []
    current_line_length = 0

    for word in words:
        word_length = len(word)
        if current_line_length + 1 + word_length <= width:  # +1 for the space
            if line:
                current_line_length += 1
            line.append(word)
            current_line_length += word_length
        else:
            yield ' '.join(line)
            line = [word]
            current_line_length = word_length

    if line:
        yield ' '.join(line)

def word_wrap(text, width):
    if width <= 0:
        raise ValueError("Width must be greater than 0")

    words = text.split()
    if not words:
        return []

    line = []
    wrapped_lines = []

    for word in words:
        if len(line) > 0 and sum(len(w) + 1 for w in line) + len(word) > width:
            wrapped_lines.append(' '.join(line))
            line = [word]
        else:
