def merge_k_sorted(lists):
    import heapq
    min_heap = []

    # Initialize the heap with the first element of each list
    for i, lst in enumerate(lists):
        if lst:
            heapq.heappush(min_heap, (lst[0], i, 0))

    result = []

    while min_heap:
        val, list_idx, element_idx = heapq.heappop(min_heap)
        result.append(val)

        # If there are more elements in the list, push the next element into the heap
        if element_idx + 1 < len(lists[list_idx]) and lists[list_idx][element_idx + 1]:
            next_val = lists[list_idx][element_idx + 1]
            heapq.heappush(min_heap, (next_val, list_idx, element_idx + 1))

    return result

from datetime import timedelta, datetime

def add_business_days(date_str, n):
    date = datetime.strptime(date_str, "%Y-%m-%d")

    if n < 0:
        raise ValueError("n must be a non-negative integer")

    for _ in range(n):
        date += timedelta(days=1)
        # Adjust to next business day if it's a weekend
        while date.weekday() >= 5:  # 5=Fri, 6=Sat
            date += timedelta(days=1)

    return date.strftime("%Y-%m-%d")

